'use strict';
const storage = require('./storage');
const t = require('./todos');

const USAGE = `Usage:
  node index.js add "<text>"
  node index.js list
  node index.js complete <id>
  node index.js delete <id>`;

/**
 * Run a command. Returns the exit code; output goes through the injected
 * streams so tests can capture it.
 */
function run(argv, { file, out = console.log, err = console.error } = {}) {
  const [command, ...args] = argv;
  try {
    switch (command) {
      case 'add': {
        if (args.length > 1) throw new t.UsageError('Quote multi-word text: add "<text>"');
        const r = t.addTodo(storage.load(file), args[0]);
        storage.save(r.todos, file);
        out(`Added todo ${r.todo.id}: ${r.todo.text}`);
        return 0;
      }
      case 'list':
        out(t.formatList(storage.load(file)));
        return 0;
      case 'complete': {
        const r = t.completeTodo(storage.load(file), t.parseId(args[0]));
        storage.save(r.todos, file);
        out(`Completed todo ${r.todo.id}: ${r.todo.text}`);
        return 0;
      }
      case 'delete': {
        const r = t.deleteTodo(storage.load(file), t.parseId(args[0]));
        storage.save(r.todos, file);
        out(`Deleted todo ${r.todo.id}: ${r.todo.text}`);
        return 0;
      }
      default:
        if (command !== undefined) err(`Unknown command "${command}".`);
        err(USAGE);
        return 1;
    }
  } catch (e) {
    err(`Error: ${e.message}`);
    return 1;
  }
}

module.exports = { run, USAGE };
