'use strict';
const { test, describe } = require('node:test');
const assert = require('node:assert');
const t = require('../src/todos');

const base = [
  { id: 1, text: 'a', completed: false, createdAt: 'x' },
  { id: 3, text: 'b', completed: false, createdAt: 'x' },
];

describe('todos unit', () => {
  test('addTodo assigns max+1 id and ISO timestamp', () => {
    const { todo } = t.addTodo(base, ' hi ', new Date('2020-01-01T00:00:00Z'));
    assert.deepStrictEqual(todo, { id: 4, text: 'hi', completed: false, createdAt: '2020-01-01T00:00:00.000Z' });
  });
  test('addTodo starts at id 1 on empty list', () => {
    assert.strictEqual(t.addTodo([], 'x').todo.id, 1);
  });
  test('addTodo does not mutate input', () => {
    const copy = JSON.parse(JSON.stringify(base));
    t.addTodo(base, 'x');
    assert.deepStrictEqual(base, copy);
  });
  test('completeTodo marks done without mutating input', () => {
    const { todos } = t.completeTodo(base, 3);
    assert.strictEqual(todos[1].completed, true);
    assert.strictEqual(base[1].completed, false);
  });
  test('deleteTodo removes only the target', () => {
    assert.deepStrictEqual(t.deleteTodo(base, 1).todos.map((x) => x.id), [3]);
  });
  test('formatList shows id, indicator and text', () => {
    const list = [{ ...base[0], completed: true }, base[1]];
    assert.strictEqual(t.formatList(list), '1 [x] a\n3 [ ] b');
  });
  test('formatList handles empty list', () => {
    assert.strictEqual(t.formatList([]), 'No todos yet.');
  });
  test('parseId accepts positive integers', () => {
    assert.strictEqual(t.parseId('12'), 12);
  });
});
