'use strict';
const { test, describe } = require('node:test');
const assert = require('node:assert');
const fs = require('fs');
const os = require('os');
const path = require('path');
const t = require('../src/todos');
const storage = require('../src/storage');

describe('edge cases', () => {
  for (const bad of [undefined, '', 'abc', '0', '-1', '1.5', '1e2', ' 1', '99999999999999999999']) {
    test(`parseId rejects ${JSON.stringify(bad)}`, () => {
      assert.throws(() => t.parseId(bad), t.UsageError);
    });
  }
  for (const bad of [undefined, '', '   ', 42]) {
    test(`addTodo rejects ${JSON.stringify(bad)}`, () => {
      assert.throws(() => t.addTodo([], bad), t.UsageError);
    });
  }
  test('complete/delete unknown id throws', () => {
    assert.throws(() => t.completeTodo([], 1), /No todo with id 1/);
    assert.throws(() => t.deleteTodo([], 1), /No todo with id 1/);
  });
  test('unicode text is preserved', () => {
    assert.strictEqual(t.addTodo([], 'café ☕ 日本').todo.text, 'café ☕ 日本');
  });
  describe('storage', () => {
    const mk = () => path.join(fs.mkdtempSync(path.join(os.tmpdir(), 'todo-')), 'todos.json');
    test('missing file loads as empty', () => assert.deepStrictEqual(storage.load(mk()), []));
    test('empty file loads as empty', () => {
      const f = mk();
      fs.writeFileSync(f, '  ');
      assert.deepStrictEqual(storage.load(f), []);
    });
    test('corrupt JSON throws with path', () => {
      const f = mk();
      fs.writeFileSync(f, '{oops');
      assert.throws(() => storage.load(f), new RegExp('not valid JSON'));
    });
    test('non-array JSON throws', () => {
      const f = mk();
      fs.writeFileSync(f, '{}');
      assert.throws(() => storage.load(f), /JSON array/);
    });
    test('save/load roundtrip leaves no temp files', () => {
      const f = mk();
      storage.save([{ id: 1 }], f);
      assert.deepStrictEqual(storage.load(f), [{ id: 1 }]);
      assert.deepStrictEqual(fs.readdirSync(path.dirname(f)), ['todos.json']);
    });
    test('save to missing directory throws', () => {
      assert.throws(() => storage.save([], '/nonexistent-dir/x.json'), /Cannot write/);
    });
  });
});
