'use strict';
const { test, describe, beforeEach } = require('node:test');
const assert = require('node:assert');
const fs = require('fs');
const os = require('os');
const path = require('path');
const { spawnSync } = require('child_process');
const { run } = require('../src/cli');

const INDEX = path.join(__dirname, '..', 'index.js');
let dir, file, outs, errs;
const call = (...argv) => run(argv, { file, out: (s) => outs.push(s), err: (s) => errs.push(s) });
const stored = () => JSON.parse(fs.readFileSync(file, 'utf8'));

beforeEach(() => {
  dir = fs.mkdtempSync(path.join(os.tmpdir(), 'todo-cli-'));
  file = path.join(dir, 'todos.json');
  outs = [];
  errs = [];
});

describe('cli commands', () => {
  test('add creates file with expected fields', () => {
    assert.strictEqual(call('add', 'Buy groceries'), 0);
    const [todo] = stored();
    assert.strictEqual(todo.id, 1);
    assert.strictEqual(todo.text, 'Buy groceries');
    assert.strictEqual(todo.completed, false);
    assert.ok(!Number.isNaN(Date.parse(todo.createdAt)));
  });
  test('ids auto-increment and are not reused after deleting the last', () => {
    call('add', 'a'); call('add', 'b'); call('delete', '2'); call('add', 'c');
    assert.deepStrictEqual(stored().map((x) => x.id), [1, 2]);
    call('delete', '1'); call('add', 'd');
    assert.deepStrictEqual(stored().map((x) => x.id), [2, 3]);
  });
  test('list on empty shows message', () => {
    assert.strictEqual(call('list'), 0);
    assert.deepStrictEqual(outs, ['No todos yet.']);
    assert.ok(!fs.existsSync(file));
  });
  test('list shows pending and done', () => {
    call('add', 'a'); call('add', 'b'); call('complete', '1');
    outs = [];
    call('list');
    assert.strictEqual(outs[0], '1 [x] a\n2 [ ] b');
  });
  test('complete persists and is idempotent', () => {
    call('add', 'a');
    assert.strictEqual(call('complete', '1'), 0);
    assert.strictEqual(call('complete', '1'), 0);
    assert.strictEqual(stored()[0].completed, true);
  });
  test('delete removes todo', () => {
    call('add', 'a');
    assert.strictEqual(call('delete', '1'), 0);
    assert.deepStrictEqual(stored(), []);
  });
});

describe('cli errors', () => {
  test('add without text fails', () => {
    assert.strictEqual(call('add'), 1);
    assert.match(errs[0], /required/);
    assert.ok(!fs.existsSync(file));
  });
  test('add with unquoted extra args fails', () => {
    assert.strictEqual(call('add', 'a', 'b'), 1);
  });
  for (const cmd of ['complete', 'delete']) {
    test(`${cmd} without id fails`, () => {
      assert.strictEqual(call(cmd), 1);
      assert.match(errs[0], /id is required/);
    });
    test(`${cmd} with non-numeric id fails`, () => {
      assert.strictEqual(call(cmd, 'abc'), 1);
      assert.match(errs[0], /Invalid id/);
    });
    test(`${cmd} with unknown id fails and leaves data intact`, () => {
      call('add', 'a');
      assert.strictEqual(call(cmd, '9'), 1);
      assert.match(errs[errs.length - 1], /No todo with id 9/);
      assert.strictEqual(stored().length, 1);
    });
  }
  test('unknown command prints usage', () => {
    assert.strictEqual(call('frobnicate'), 1);
    assert.match(errs.join('\n'), /Unknown command[\s\S]*Usage/);
  });
  test('no command prints usage', () => {
    assert.strictEqual(call(), 1);
    assert.match(errs[0], /Usage/);
  });
  test('corrupt file reports error and is not overwritten', () => {
    fs.writeFileSync(file, 'garbage');
    assert.strictEqual(call('add', 'x'), 1);
    assert.strictEqual(fs.readFileSync(file, 'utf8'), 'garbage');
  });
});

describe('end-to-end via process', () => {
  const exec = (...args) => spawnSync('node', [INDEX, ...args], { cwd: dir, encoding: 'utf8' });
  test('full flow writes todos.json in cwd', () => {
    assert.strictEqual(exec('add', 'Buy groceries').status, 0);
    assert.strictEqual(exec('list').stdout.trim(), '1 [ ] Buy groceries');
    exec('complete', '1');
    assert.strictEqual(exec('list').stdout.trim(), '1 [x] Buy groceries');
    exec('delete', '1');
    assert.strictEqual(exec('list').stdout.trim(), 'No todos yet.');
    assert.ok(fs.existsSync(path.join(dir, 'todos.json')));
  });
  test('bad id exits non-zero with stderr', () => {
    const r = exec('complete', 'x');
    assert.strictEqual(r.status, 1);
    assert.match(r.stderr, /Invalid id/);
  });
});
